import httpx
from prefect import flow, task

@task(retries=3, retry_delay_seconds=10, tags=["api_calcul"])
def appeler_api(a: int, b: int) -> int:
    with httpx.Client(timeout=10.0) as client:
        r = client.get("http://localhost:8000/calcul", params={"a": a, "b": b})
        r.raise_for_status()
        return r.json()["resultat"]

@flow(name="Calculs en parallèle", log_prints=True)
def pipeline_calcul(n: int = 10) -> list[int]:
    futures = [appeler_api.submit(i, i + 1) for i in range(n)]
    resultats = [f.result() for f in futures]
    print(f"{len(resultats)} calculs terminés")
    return resultats

if __name__ == "__main__":
    pipeline_calcul.serve(name="calcul-auto", cron="0 9 * * *")   # tous les jours à 9 h

