import csv

import httpx
from prefect import flow, task

@task(retries=3, retry_delay_seconds=5)
def extraire(url: str) -> list[dict]:
    r = httpx.get(url, timeout=10)
    r.raise_for_status()
    return r.json()

@task
def transformer(lignes: list[dict]) -> list[dict]:
    return [l for l in lignes if all(v not in (None, "") for v in l.values())]

@task
def charger(lignes: list[dict], chemin: str = "sortie.csv") -> int:
    if lignes:
        with open(chemin, "w", newline="", encoding="utf-8") as f:
            w = csv.DictWriter(f, fieldnames=list(lignes[0]))
            w.writeheader()
            w.writerows(lignes)
    return len(lignes)

@flow(log_prints=True)
def etl(url: str):
    n = charger(transformer(extraire(url)))
    print(f"{n} lignes chargées")
